शब्दादीन्विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च ॥ ५१ ॥
विविक्तसेवी लघ्वाशी यतवाक्कायमानस: ।
ध्यानयोगपरो नित्यं वैराग्यं समुपाश्रित: ॥ ५२ ॥
अहङ्कारं बलं दर्पं कामं क्रोधं परिग्रहम् ।
विमुच्य निर्मम: शान्तो ब्रह्मभूयाय कल्पते ॥ ५३ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4733,\"bb\":4142,\"url_path\":\"/en/library/bg/18/51-53/b4142/\",\"body_value\":\"buddhyā viśuddhayā yukto
dhṛtyātmānaṁ niyamya ca
śabdādīn viṣayāṁs tyaktvā
rāga-dveṣau vyudasya ca\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4734,\"bb\":4143,\"url_path\":\"/en/library/bg/18/51-53/b4143/\",\"body_value\":\"vivikta-sevī laghv-āśī
yata-vāk-kāya-mānasaḥ
dhyāna-yoga-paro nityaṁ
vairāgyaṁ samupāśritaḥ\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4735,\"bb\":4144,\"url_path\":\"/en/library/bg/18/51-53/b4144/\",\"body_value\":\"ahaṅkāraṁ balaṁ darpaṁ
kāmaṁ krodhaṁ parigraham
vimucya nirmamaḥ śānto
brahma-bhūyāya kalpate\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4736,\"bb\":4145,\"url_path\":\"/en/library/bg/18/51-53/b4145/\",\"shadow_value\":\"$25\",\"word_for_word_value\":[{\"word\":\"buddhyā\",\"translation\":\"with the intelligence\"},{\"word\":\"viśuddhayā\",\"translation\":\"fully purified\"},{\"word\":\"yuktaḥ\",\"translation\":\"engaged\"},{\"word\":\"dhṛtyā\",\"translation\":\"by determination\"},{\"word\":\"ātmānam\",\"translation\":\"the self\"},{\"word\":\"niyamya\",\"translation\":\"regulating\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"śabda-ādīn\",\"translation\":\"such as sound\"},{\"word\":\"viṣayān\",\"translation\":\"the sense objects\"},{\"word\":\"tyaktvā\",\"translation\":\"giving up\"},{\"word\":\"rāga\",\"translation\":\"attachment\"},{\"word\":\"dveṣau\",\"translation\":\"and hatred\"},{\"word\":\"vyudasya\",\"translation\":\"laying aside\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"vivikta-sevī\",\"translation\":\"living in a secluded place\"},{\"word\":\"laghu-āśī\",\"translation\":\"eating a small quantity\"},{\"word\":\"yata\",\"translation\":\"having controlled\"},{\"word\":\"vāk\",\"translation\":\"speech\"},{\"word\":\"kāya\",\"translation\":\"body\"},{\"word\":\"mānasaḥ\",\"translation\":\"and mind\"},{\"word\":\"dhyāna-yoga-paraḥ\",\"translation\":\"absorbed in trance\"},{\"word\":\"nityam\",\"translation\":\"twenty-four hours a day\"},{\"word\":\"vairāgyam\",\"translation\":\"detachment\"},{\"word\":\"samupāśritaḥ\",\"translation\":\"having taken shelter of\"},{\"word\":\"ahaṅkāram\",\"translation\":\"false ego\"},{\"word\":\"balam\",\"translation\":\"false strength\"},{\"word\":\"darpam\",\"translation\":\"false pride\"},{\"word\":\"kāmam\",\"translation\":\"lust\"},{\"word\":\"krodham\",\"translation\":\"anger\"},{\"word\":\"parigraham\",\"translation\":\"and acceptance of material things\"},{\"word\":\"vimucya\",\"translation\":\"being delivered from\"},{\"word\":\"nirmamaḥ\",\"translation\":\"without a sense of proprietorship\"},{\"word\":\"śāntaḥ\",\"translation\":\"peaceful\"},{\"word\":\"brahma-bhūyāya\",\"translation\":\"for self-realization\"},{\"word\":\"kalpate\",\"translation\":\"is qualified\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4737,\"bb\":4146,\"url_path\":\"/en/library/bg/18/51-53/b4146/\",\"body_value\":\"Being purified by his intelligence and controlling the mind with determination, giving up the objects of sense gratification, being freed from attachment and hatred, one who lives in a secluded place, who eats little, who controls his body, mind and power of speech, who is always in trance and who is detached, free from false ego, false strength, false pride, lust, anger, and acceptance of material things, free from false proprietorship, and peaceful – such a person is certainly elevated to the position of self-realization.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4738,\"bb\":4147,\"url_path\":\"/en/library/bg/18/51-53/b4147/\",\"body_value\":\"$26\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4739,\"bb\":4148,\"url_path\":\"/en/library/bg/18/51-53/b4148/\",\"body_value\":\"āpūryamāṇam acala-pratiṣṭhaṁ
samudram āpaḥ praviśanti yadvat
tadvat kāmā yaṁ praviśanti sarve
sa śāntim āpnoti na kāma-kāmī\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4740,\"bb\":4149,\"url_path\":\"/en/library/bg/18/51-53/b4149/\",\"body_value\":\"“A person who is not disturbed by the incessant flow of desires – that enter like rivers into the ocean, which is ever being filled but is always still – can alone achieve peace, and not the man who strives to satisfy such desires.”\"}]}],\"short_title\":\"Bg. 18.51-53\",\"medium_title\":\"Bhagavad-gītā As It Is 18.51-53\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L27\",\"$L28\",\"$L29\"]}]\n"])self.__next_f.push([1,"2b:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n31:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n27:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"clas