\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":4749,\"bb\":568519,\"url_path\":\"/en/library/bg/18/55/devanagari/\",\"body_final\":\"भक्त्य‍ा मामभिजानाति यावान्यश्चास्मि तत्त्वत: ।
ततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम् ॥ ५५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4750,\"bb\":4157,\"url_path\":\"/en/library/bg/18/55/b4157/\",\"body_value\":\"bhaktyā mām abhijānāti
yāvān yaś cāsmi tattvataḥ
tato māṁ tattvato jñātvā
viśate tad-anantaram\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4751,\"bb\":4158,\"url_path\":\"/en/library/bg/18/55/b4158/\",\"shadow_value\":\"bhaktyā – by pure devotional service; mām – Me; abhijānāti – one can know; yāvān – as much as; yaḥ ca asmi – as I am; tattvataḥ – in truth; tataḥ – thereafter; mām – Me; tattvataḥ – in truth; jñātvā – knowing; viśate – he enters; tat-anantaram – thereafter.\",\"word_for_word_value\":[{\"word\":\"bhaktyā\",\"translation\":\"by pure devotional service\"},{\"word\":\"mām\",\"translation\":\"Me\"},{\"word\":\"abhijānāti\",\"translation\":\"one can know\"},{\"word\":\"yāvān\",\"translation\":\"as much as\"},{\"word\":\"yaḥ ca asmi\",\"translation\":\"as I am\"},{\"word\":\"tattvataḥ\",\"translation\":\"in truth\"},{\"word\":\"tataḥ\",\"translation\":\"thereafter\"},{\"word\":\"mām\",\"translation\":\"Me\"},{\"word\":\"tattvataḥ\",\"translation\":\"in truth\"},{\"word\":\"jñātvā\",\"translation\":\"knowing\"},{\"word\":\"viśate\",\"translation\":\"he enters\"},{\"word\":\"tat-anantaram\",\"translation\":\"thereafter\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4752,\"bb\":4159,\"url_path\":\"/en/library/bg/18/55/b4159/\",\"body_value\":\"One can understand Me as I am, as the Supreme Personality of Godhead, only by devotional service. And when one is in full consciousness of Me by such devotion, he can enter into the kingdom of God.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4753,\"bb\":4160,\"url_path\":\"/en/library/bg/18/55/b4160/\",\"body_value\":\"The Supreme Personality of Godhead, Kṛṣṇa, and His plenary portions cannot be understood by mental speculation nor by the nondevotees. If anyone wants to understand the Supreme Personality of Godhead, he has to take to pure devotional service under the guidance of a pure devotee. Otherwise, the truth of the Supreme Personality of Godhead will always be hidden. As already stated in Bhagavad-gītā (7.25), nāhaṁ prakāśaḥ sarvasya: He is not revealed to everyone. No one can understand God simply by erudite scholarship or mental speculation. Only one who is actually engaged in Kṛṣṇa consciousness and devotional service can understand what Kṛṣṇa is. University degrees are not helpful.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4754,\"bb\":4161,\"url_path\":\"/en/library/bg/18/55/b4161/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4755,\"bb\":4162,\"url_path\":\"/en/library/bg/18/55/b4162/\",\"body_value\":\"Because of his pure devotional service, a devotee can understand the transcendental qualities and the opulences of the Supreme Lord in truth. As it is stated in the Eleventh Chapter, only by devotional service can one understand. The same is confirmed here; one can understand the Supreme Personality of Godhead by devotional service and enter into His kingdom.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4756,\"bb\":4163,\"url_path\":\"/en/library/bg/18/55/b4163/\",\"body_value\":\"$26\"}]}],\"short_title\":\"Bg. 18.55\",\"medium_title\":\"Bhagavad-gītā As It Is 18.55\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L27\",\"$L28\",\"$L29\"]}]\n"])self.__next_f.push([1,"2b:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n31:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chun